import pytest
from candidate import digitSum

def test_empty_string_returns_zero():
    assert digitSum("") == 0

def test_mixed_case_abab_returns_131():
    assert digitSum("abAB") == 131

def test_lowercase_with_one_uppercase_returns_correct_ascii():
    assert digitSum("abcCd") == 67

def test_uppercase_at_end_returns_correct_ascii():
    assert digitSum("helloE") == 69

def test_multiple_uppercases_spaced_out_returns_correct_sum():
    assert digitSum("woArBld") == 131

def test_spread_uppercases_returns_correct_sum():
    assert digitSum("aAaaaXa") == 153

def test_no_uppercase_characters_returns_zero():
    assert digitSum("hello") == 0

def test_all_uppercase_string_returns_full_ascii_sum():
    assert digitSum("ABC") == 198

def test_single_uppercase_character_returns_its_ascii():
    assert digitSum("Z") == 90

def test_single_lowercase_character_returns_zero():
    assert digitSum("z") == 0

